package com.bike.server.rework;

import java.time.LocalDateTime;

public class ReworkView { private Long id; private String reworkNo; private String frameSn; private String reason; private String status; private String partType; private String oldPartSn; private String newPartSn; private LocalDateTime operationTime; public Long getId(){return id;} public void setId(Long v){id=v;} public String getReworkNo(){return reworkNo;} public void setReworkNo(String v){reworkNo=v;} public String getFrameSn(){return frameSn;} public void setFrameSn(String v){frameSn=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getPartType(){return partType;} public void setPartType(String v){partType=v;} public String getOldPartSn(){return oldPartSn;} public void setOldPartSn(String v){oldPartSn=v;} public String getNewPartSn(){return newPartSn;} public void setNewPartSn(String v){newPartSn=v;} public LocalDateTime getOperationTime(){return operationTime;} public void setOperationTime(LocalDateTime v){operationTime=v;} }
